      {
        "src": "/assets/stories/debu-yang-menari/illustrations/scene-111-df064092-0faf-40f3-a053-6a2a76a1d0e1.jpg",
        "alt": "Ilustrasi adegan dari cerpen Debu yang Menari",
        "source": "illustrations/scene-111-df064092-0faf-40f3-a053-6a2a76a1d0e1.jpg"
      }
