      {
        "src": "/assets/stories/suara-di-balai-muafakat/illustrations/d961dc86-85f1-46e7-a489-59776c226dd8.jpg",
        "alt": "Ilustrasi adegan dari cerpen Suara di Balai Muafakat",
        "source": "illustrations/d961dc86-85f1-46e7-a489-59776c226dd8.jpg"
      }
